charts.transform_with:
// Transform chart data before rendering.
// Following function is called when new data arrives, and again with `completed = true` after all data arrives.
// You can transform the data here arbitrarily.
// Most chart types expect columns 'time', 'value' and optionally 'series' by default.
async (existingDataByQuery, newDataByQuery, completed) => {
  return Object.keys(newDataByQuery).reduce((result, queryIndex) => {
    result[queryIndex] = result[queryIndex].concat(newDataByQuery[queryIndex]);
    return result;
  }, existingDataByQuery);
}

