chart_queries.sql_query:
SELECT
  IF(
    countMergeIf(events_count, provider_restart = 'false') > 0,
    countMerge(latency_seconds_valid_count) * 100.0
      / countMergeIf(events_count, provider_restart = 'false'),
    NULL
  ) AS "Validity %"
FROM {{source}}
WHERE dt BETWEEN {{start_time}} AND {{end_time}}

